731→// --- Helpers ---
732→
733→func nonEmptyLines(data []byte) []string {
734→	var lines []string
735→	for _, line := range strings.Split(string(data), "\n") {
736→		if strings.TrimSpace(line) != "" {
737→			lines = append(lines, line)
738→		}
739→	}
740→	return lines
741→}
742→
743→// assertJSONLines compares actual output lines against expected JSON strings,
744→// using semantic JSON equality (order-independent for object keys).
745→func assertJSONLines(t *testing.T, actual []byte, expected []string) {
746→	t.Helper()
747→
748→	actualLines := nonEmptyLines(actual)
749→
750→	if len(expected) == 0 && len(actualLines) == 0 {
751→		return
752→	}
753→
754→	if len(actualLines) != len(expected) {
755→		t.Fatalf("line count mismatch: got %d, want %d\nactual:\n%s", len(actualLines), len(expected), string(actual))
756→	}
757→
758→	for i := range expected {
759→		var got, want interface{}
760→		if err := json.Unmarshal([]byte(actualLines[i]), &got); err != nil {
761→			t.Fatalf("line %d: failed to parse actual JSON: %v\nline: %s", i, err, actualLines[i])
762→		}
763→		if err := json.Unmarshal([]byte(expected[i]), &want); err != nil {
764→			t.Fatalf("line %d: failed to parse expected JSON: %v\nline: %s", i, err, expected[i])
765→		}
766→		if !reflect.DeepEqual(got, want) {
767→			prettyGot, _ := json.MarshalIndent(got, "", "  ")
768→			prettyWant, _ := json.MarshalIndent(want, "", "  ")
769→			t.Errorf("line %d mismatch:\ngot:\n%s\nwant:\n%s", i, prettyGot, prettyWant)
770→		}
771→	}
772→}
