//go:build ignore

package main

import (
	"fmt"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

func main() {
	agent := os.Args[1]
	inFile := os.Args[2]
	outFile := os.Args[3]

	content, err := os.ReadFile(inFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "read %s: %v\n", inFile, err)
		os.Exit(1)
	}

	result, err := transcript.Compact(content, transcript.CompactOptions{
		Agent:      agent,
		CLIVersion: "0.5.1",
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "compact: %v\n", err)
		os.Exit(1)
	}

	if err := os.WriteFile(outFile, result, 0644); err != nil {
		fmt.Fprintf(os.Stderr, "write %s: %v\n", outFile, err)
		os.Exit(1)
	}
	fmt.Fprintf(os.Stderr, "wrote %d bytes to %s\n", len(result), outFile)
}
GOEOF
